package corpus.arrayinit

fun zerosWithAudit(): Pair<IntArray, Int> {
    var visited = 0
    val result = IntArray(4) { index ->
        visited += index
        0
    }
    return result to visited
}

package corpus.arrayinit

class IntArray(private val length: Int, private val read: (Int) -> Int) {
    operator fun get(index: Int): Int {
        require(index in 0 until length)
        return read(index)
    }
}

fun lazyZeros(): IntArray = IntArray(4) { 0 }
